-- Тема 09: варианты ответов выровнены по длине и форме (36 исправлений в 11 вопросах), ключи не меняются.
-- Источник: scripts/questions/077_option_length_topic09.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('option', 'Чем information_schema отличается от pg_catalog?', 'Определена стандартом SQL, стабильнее и переносимее, но не отражает специфику PostgreSQL', 'Определена стандартом SQL, не описывает особенности PostgreSQL', 'Определена стандартом SQL и поэтому переносимее, хотя реализации в разных СУБД могут различаться.', 'Определена стандартом SQL и поэтому стабильнее и переносимее, хотя реализации в разных СУБД могут различаться; особенности PostgreSQL она не отражает.'),
        ('option', 'Чем information_schema отличается от pg_catalog?', 'Содержит данные пользовательских таблиц', 'Содержит строки пользовательских таблиц каждой базы кластера', 'Она описывает объекты, а не хранит их данные.', NULL),
        ('option', 'Чем information_schema отличается от pg_catalog?', 'Доступна только суперпользователю', 'Доступна для чтения суперпользователю кластера', 'Доступна всем и показывает объекты, к которым есть доступ.', NULL),
        ('option', 'Чем information_schema отличается от pg_catalog?', 'Хранится вне баз данных', 'Хранится вне баз данных, в общем каталоге кластера', 'Это схема внутри каждой базы данных.', NULL),
        ('option', 'Что из перечисленного — общий для всего кластера объект системного каталога?', 'Список таблиц (pg_class)', 'Список таблиц каждой базы (pg_class)', 'Своя таблица в каждой базе.', NULL),
        ('option', 'Что из перечисленного — общий для всего кластера объект системного каталога?', 'Столбцы таблиц (pg_attribute)', 'Столбцы таблиц каждой базы (pg_attribute)', 'Своя таблица в каждой базе.', NULL),
        ('option', 'Что из перечисленного — общий для всего кластера объект системного каталога?', 'Функции (pg_proc)', 'Функции каждой базы (pg_proc)', 'Своя таблица в каждой базе.', NULL),
        ('option', 'Как обычно устроены имена столбцов в таблицах системного каталога?', 'Префикс pg_ перед каждым столбцом', 'Префикс pg_ у каждого столбца таблицы', 'Префикс pg_ у имён таблиц, а не столбцов.', NULL),
        ('option', 'Как обычно устроены имена столбцов в таблицах системного каталога?', 'Имена в верхнем регистре', 'Имена столбцов в верхнем регистре', 'Имена в каталоге в нижнем регистре.', NULL),
        ('option', 'Как обычно устроены имена столбцов в таблицах системного каталога?', 'Имена из стандарта SQL', 'Имена столбцов по стандарту SQL', 'Такие имена используются в information_schema.', NULL),
        ('option', 'Как обычно устроены имена столбцов в таблицах системного каталога?', 'Трёхбуквенный префикс без подчёркивания, например datname', 'Короткий префикс без подчёркивания (datname)', 'Например, у pg_database столбцы datname и datdba.', 'У столбцов каталога обычно короткий префикс без подчёркивания: например, у pg_database столбцы datname и datdba.'),
        ('option', 'Что представляет собой тип данных oid?', '32-битный целочисленный идентификатор объекта', '32-битный числовой идентификатор объекта', 'Около 4 млрд значений.', NULL),
        ('option', 'Что представляет собой тип данных oid?', '64-битный целочисленный идентификатор', '64-битный числовой идентификатор объекта', 'Тип oid 32-битный.', NULL),
        ('option', 'Для чего нужны типы reg*, например regclass?', 'Для работы с регулярными выражениями', 'Для работы с регулярными выражениями в запросах', 'Для регулярных выражений есть операторы ~ и функции regexp_*.', NULL),
        ('option', 'Для чего нужны типы reg*, например regclass?', 'Для регистрации расширений', 'Для регистрации новых расширений сервера', 'Расширения устанавливает CREATE EXTENSION.', NULL),
        ('option', 'Для чего нужны типы reg*, например regclass?', 'Для преобразования имени объекта в oid и обратно', 'Для преобразования имён объектов в oid', 'Например, regclass для отношений, regproc для функций.', 'Для преобразования имени объекта в oid и обратно: например, regclass для отношений, regproc для функций.'),
        ('option', 'Для чего нужны типы reg*, например regclass?', 'Для хранения привилегий', 'Для хранения привилегий пользователей', 'Привилегии хранятся в столбцах типа aclitem[].', NULL),
        ('option', 'Чем вывод команды \d+ отличается от \d?', 'Показывает только системные объекты', 'Показывает системные объекты вместе с обычными', 'Системные объекты добавляет модификатор S.', 'Системные объекты добавляет модификатор S, а не плюс.'),
        ('option', 'Чем вывод команды \d+ отличается от \d?', 'Показывает только привилегии', 'Показывает привилегии на объект и его столбцы', 'Привилегии показывает \dp.', NULL),
        ('option', 'Чем вывод команды \d+ отличается от \d?', 'Выполняет ANALYZE объекта', 'Запускает ANALYZE объекта перед выводом', 'Команды \d выполняют запросы к каталогу, но ANALYZE не запускают.', NULL),
        ('option', 'Чем вывод команды \d+ отличается от \d?', 'Показывает дополнительную информацию об объекте', 'Показывает дополнительные сведения об объекте', 'Например, описание, размер и параметры хранения.', NULL),
        ('option', 'Что верно для типа данных oid?', 'Используется как первичный ключ большинства таблиц каталога', 'Служит первичным ключом большинства таблиц каталога', 'У большинства таблиц каталога первичный ключ — столбец oid.', NULL),
        ('option', 'Что верно для типа данных oid?', 'Всегда 64-битный', 'Имеет 64 бита, как bigint', 'Тип oid 32-битный.', 'Тип oid 32-битный, а не 64-битный как bigint.'),
        ('option', 'Что появилось у большинства таблиц системного каталога начиная с PostgreSQL 14?', 'Триггеры на изменение', 'Триггеры на изменение строк таблиц', 'Триггеров на таблицах каталога нет.', NULL),
        ('option', 'Что появилось у большинства таблиц системного каталога начиная с PostgreSQL 14?', 'Секционирование', 'Секционирование по диапазонам значений', 'Таблицы каталога не секционируются.', NULL),
        ('option', 'Что выводит команда psql \d pg_class?', 'Права доступа к pg_class', 'Права доступа к таблице pg_class', 'Права доступа показывает команда \dp.', NULL),
        ('option', 'Что выводит команда psql \d pg_class?', 'Описание объекта pg_class: столбцы, их типы и индексы', 'Описание pg_class: столбцы и индексы', '\d от слова describe.', 'Описание объекта pg_class: столбцы, их типы и индексы; \d от слова describe.'),
        ('option', 'Что выводит команда psql \d pg_class?', 'Только размер таблицы pg_class', 'Размер таблицы pg_class на диске', 'Размер показывают подробные списки, например \dt+.', NULL),
        ('option', 'Что выводит команда psql \d pg_class?', 'Содержимое таблицы pg_class', 'Содержимое таблицы pg_class построчно', 'Строки таблицы выводит запрос SELECT.', NULL),
        ('option', 'Почему не рекомендуется создавать собственные объекты с именами на pg_?', 'Чтобы избежать конфликтов имён с объектами системного каталога', 'Чтобы не конфликтовать с объектами системного каталога', 'Все таблицы и представления каталога начинаются с pg_.', NULL),
        ('option', 'Почему не рекомендуется создавать собственные объекты с именами на pg_?', 'Такие имена запрещены для любых объектов', 'Такие имена запрещены для таблиц и схем', 'Для таблиц они разрешены, хотя и не рекомендуются; для схем и табличных пространств префикс pg_ зарезервирован.', NULL),
        ('option', 'Почему не рекомендуется создавать собственные объекты с именами на pg_?', 'Такие объекты автоматически становятся общими для кластера', 'Такие объекты становятся общими для кластера', 'Общие объекты определяются устройством каталога, а не именем.', NULL),
        ('option', 'Что верно для системного каталога?', 'Он хранится в самом кластере в виде таблиц и представлений', 'Он хранится в самом кластере в виде таблиц', 'Это метаинформация о кластере внутри кластера.', 'Это метаинформация о кластере внутри кластера: таблицы и представления.'),
        ('option', 'Что верно для системного каталога?', 'Он хранится в файле postgresql.conf', 'Он хранится в файле postgresql.conf кластера', 'В этом файле хранятся параметры конфигурации.', NULL),
        ('option', 'Что верно для системного каталога?', 'Его можно читать обычными запросами SELECT', 'Его можно читать обычными запросами', 'Клиентские программы так и получают описание объектов.', 'Его можно читать обычными запросами SELECT: клиентские программы так и получают описание объектов.'),
        ('option', 'Что верно для системного каталога?', 'Он полностью общий для всех баз кластера', 'Он общий для всех баз кластера целиком', 'Общая лишь часть таблиц, остальные есть в каждой базе.', NULL)
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
